use std::{cell::Cell, collections::BTreeSet, time::Instant};
fn main() {
    let scale = std::env::args().nth(1).unwrap().parse::<usize>().unwrap();
    let seed = [(0, )];
    let edges: Vec<_> = (0..scale as i32).map(|i| (i, i + 1)).collect();
    let reachable: BTreeSet<_> = (1..=scale as i32).map(|i| (i,)).collect();
    let rounds = Cell::new(0);
    let delta_rows = Cell::new(0);
    let start = Instant::now();
    let actual: BTreeSet<_> = mini_linq::compile! {
        pipeline { surface = [cq_ext_recursion::recursion]; }
        recursion! {
            observe = |_:usize, rows:usize| { rounds.set(rounds.get()+1); delta_rows.set(delta_rows.get()+rows); };
            struct Path;
            relation seed(x:i32);
            relation edges(x:i32,y:i32);
            relation reach(x:i32);
            reach(*y) :- seed(x), edges(x,y); reach(*z) :- reach(y), edges(y,z);
        }
    }.collect();
    let elapsed = start.elapsed();
    assert_eq!(actual, reachable);
    assert_eq!(rounds.get(), scale);
    assert_eq!(delta_rows.get(), scale);
    println!("recursion_ns={} rounds={} delta_rows={}", elapsed.as_nanos(), rounds.get(), delta_rows.get());
}

