fn emit(name: &str) {
    let c = cq_workloads::measurement::snapshot();
    println!("target={} hash_computations={} index_builds={} lookups={} cursor_steps={} rows_enumerated={} distinct_insertions={}", name, c.hash_computations, c.index_builds, c.lookups, c.cursor_steps, c.rows_enumerated, c.distinct_insertions);
}
fn main() {
    assert!(cq_workloads::measurement::INSTRUMENTED);
    let checks: &[(&str, fn(cq_workloads::Scenario))] = &[
        ("aggregate_stats", cq_workloads::queries::extended::aggregate_stats::check),
        ("aggregate_two_keys", cq_workloads::queries::extended::aggregate_two_keys::check),
        ("correlated_exists", cq_workloads::queries::extended::correlated_exists::check),
        ("correlated_parameter", cq_workloads::queries::extended::correlated_parameter::check),
        ("correlated_scalar", cq_workloads::queries::extended::correlated_scalar::check),
        ("recursion_closure", cq_workloads::queries::extended::recursion_closure::check),
        ("surface_boolean_guard", cq_workloads::queries::extended::surface_boolean_guard::check),
        ("surface_compare", cq_workloads::queries::extended::surface_compare::check),
        ("surface_computed_head", cq_workloads::queries::extended::surface_computed_head::check),
        ("surface_disconnected", cq_workloads::queries::extended::surface_disconnected::check),
        ("surface_let_chain", cq_workloads::queries::extended::surface_let_chain::check),
        ("surface_let_sum", cq_workloads::queries::extended::surface_let_sum::check),
        ("surface_self_join", cq_workloads::queries::extended::surface_self_join::check),
        ("surface_wildcards", cq_workloads::queries::extended::surface_wildcards::check),
        ("union_project", cq_workloads::queries::extended::union_project::check),
        ("union_two", cq_workloads::queries::extended::union_two::check)
    ];
    for (name, check) in checks {
        cq_workloads::measurement::reset();
        for scenario in cq_workloads::Scenario::ALL { check(scenario); }
        emit(name);
    }
    cq_workloads::measurement::reset();
    cq_workloads::queries::typed::typed_line_filter::run(cq_workloads::typed::Source::Csv);
    emit("typed_line_filter");
}

reproduction.pairs_collector:
import fcntl
import json
from pathlib import Path
import random
import re
import resource
import statistics
import subprocess
import time

ROOT = Path('/data/mini_linq-wt/c7-open-issues')
EVIDENCE = ROOT / 'target/c7-evidence'
commands = {
    'recursion-path-4096': {
        label: [str(EVIDENCE / ('bench-' + label) / 'target/release' / ('c7-recursion-bench-' + label)), '4096']
        for label in ['baseline', 'working']
    },
    'doop-xalan-invariants': {
        'baseline': [str(EVIDENCE / 'baseline/features/datalog/target/release/doop'), '/tmp/doop-data/xalan', '--engine', 'mini'],
        'working': [str(ROOT / 'features/datalog/target/release/doop'), '/tmp/doop-data/xalan', '--engine', 'mini'],
    },
}

def execute(command):
    before = resource.getrusage(resource.RUSAGE_CHILDREN)
    start = time.monotonic()
    run = subprocess.run(command, cwd=ROOT, text=True, capture_output=True, check=True)
    wall = time.monotonic() - start
    after = resource.getrusage(resource.RUSAGE_CHILDREN)
    if 'recursion_ns=' in run.stdout:
        seconds = int(re.search(r'recursion_ns=(\d+)', run.stdout)[1]) / 1e9
    else:
        seconds = float(re.search(r'compute_seconds=([0-9.]+)', run.stdout)[1])
    return {'seconds': seconds, 'wall_seconds': wall, 'minor_faults': after.ru_minflt-before.ru_minflt, 'major_faults': after.ru_majflt-before.ru_majflt, 'stdout': run.stdout, 'stderr': run.stderr}

results = {'baseline': 'c1b75718', 'lock': '/tmp/mini_linq-timing.lock', 'series': {}}
with open(results['lock'], 'w') as lock:
    fcntl.flock(lock, fcntl.LOCK_EX)
    for name, variants in commands.items():
        warmups = {label: execute(command) for label, command in variants.items()}
        pairs = []
        for index in range(5):
            order = ['baseline', 'working'] if index % 2 == 0 else ['working', 'baseline']
            pair = {'order': order}
            for label in order:
                pair[label] = execute(variants[label])
            pairs.append(pair)
        ratios = [pair['working']['seconds'] / pair['baseline']['seconds'] for pair in pairs]
        rng = random.Random(2119)
        samples = sorted(statistics.mean(rng.choices(ratios, k=len(ratios))) for _ in range(10000))
        results['series'][name] = {'commands': variants, 'warmups': warmups, 'pairs': pairs, 'working_over_baseline': ratios, 'mean_ratio': statistics.mean(ratios), 'bootstrap_95_ci': [samples[250], samples[9749]]}
        print(name, results['series'][name]['mean_ratio'], results['series'][name]['bootstrap_95_ci'], flush=True)
(EVIDENCE / 'pairs.json').write_text(json.dumps(results, indent=2) + '\n')
